ruleBookInfo.tocUrl:
+<js>
var str = baseUrl; 
var id = str.replace(/(.*)bookid=(.*?)&(.*)/, '$2');
var body = "ebookid=" + id + "&pages=1&showbooklisttype=1";
var option = {
         "method": "POST",
         "body": String(body)
     }; "/showbooklist.php," + JSON.stringify(option)
 </js>

ruleToc.chapterList:
@js:
list=result.match(/href="([^"]+)">(.*?)<[\s\S]*?font>(.*?)<[\s\S]*?font>(.*?)<[\s\S]*?font>(.*?)</g);
arr=[];
number =Number(baseUrl.match(/pages=(\d+)/)[1]); number = 200*(number-1);
for(i in list){
	a=list[i].match(/href="([^"]+)">(.*?)<[\s\S]*?font>(.*?)<[\s\S]*?font>(.*?)<[\s\S]*?font>(.*?)</);
	chapternum = (Number(number)+(Number(i)+1))
	arr.push({
		"name": chapternum +"  | "+a[2].replace(/.*(重复|废废弃)章.*|^\d+[\.、]/g,''),
		"url":a[1],
		"info":"刊登时间："+a[3]+"•字数："+a[4]+"•价格："+a[5]
		})

	}
arr

ruleContent.nextContentUrl:
@js:
if(result.match(/下方留下評論後可完成敲蛋/)){
var id = result.match(/paperid: '\d+' ,bookwritercode: '([^']+)' ,bookid: '\d+'/);
code=result.match(/vercodechk.*?'[^']+'/)?result.match(/vercodechk.*?'([^']+)'/)[1]:'';

var id = id[0].replace(/: '/g, '=').replace(/' ,/g,'&').replace(/'/g,'');
var body = id + "&repapergbookid=0&papergbookpage=1&repostmsgtxt=敲&vercodechk=" + code + "&postmode=1&giftid=0";

var option = {
         "method": "POST",
         "body": String(body)
     };

result=["/papergbookresave.php," + JSON.stringify(option), "/showpapereggs.php," + JSON.stringify(option)]
}

